using NSubstitute;
using Xunit;

public interface IWeatherService
{
    Task<string> GetForecastAsync(string city);
}

[Fact]
public async Task GetForecast_Returns_Expected_City()
{
    // Arrange
    var weather = Substitute.For<IWeatherService>();
    weather.GetForecastAsync("Paris").Returns("Sunny");

    var app = new WeatherApp(weather);

    // Act
    var forecast = await app.GetLocalForecastAsync("Paris");

    // Assert
    Assert.Equal("Sunny", forecast);
    await weather.Received(1).GetForecastAsync("Paris");
}

[Fact]
public async Task GetForecast_When_Service_Fails_Throws()
{
    var weather = Substitute.For<IWeatherService>();
    weather.GetForecastAsync(Arg.Any<string>())
          .ThrowsAsync(new HttpRequestException());

    var app = new WeatherApp(weather);

    await Assert.ThrowsAsync<HttpRequestException>(
        () => app.GetLocalForecastAsync("Tokyo"));
}
